a" value="1"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button>+</button></form></div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="add">+ افزودن</button></form><?php endif;?><?php else:?><span class="muted">ناموجود</span><?php endif;?></div></article><?php endforeach;?></div></section><?php if($pages>1):?><div class="pager"><?php if($page>1):?><a href="?<?=e(http_build_query(['q'=>$q,'cat'=>$cat,'page'=>$page-1]))?>#products">قبلی</a><?php endif;?><span class="muted">صفحه <?=$page?> از <?=$pages?></span><?php if($page<$pages):?><a href="?<?=e(http_build_query(['q'=>$q,'cat'=>$cat,'page'=>$page+1]))?>#products">بعدی</a><?php endif;?></div><?php endif;?><section id="cart" class="cartbox"><div class="sectionhead"><div><h2>سبد خرید</h2><p><?=$count?> عدد کالا</p></div><b><?=toman($sub)?></b></div><?php if($rows):foreach($rows as $r):?><div class="cartline"><div class="cartmain"><?php if($r['image_path']):?><img src="<?=e($r['image_path'])?>" alt=""><?php endif;?><div><b><?=e($r['name'])?></b><div class="muted"><?=toman($r['price']*$r['qty'])?></div></div></div><div class="qty"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delta"><input type="hidden" name="delta" value="-1"><input type="hidden" name="product_id" value="<?=$r['id']?>"><input type="hidden" name="return_to" value="index.php#cart"><button>−</button></form><b><?=$r['qty']?></b><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delta"><input type="hidden" name="delta" value="1"><input type="hidden" name="product_id" value="<?=$r['id']?>"><input type="hidden" name="return_to" value="index.php#cart"><button>+</button></form></div></div><?php endforeach;?><h3 id="checkout">اطلاعات تحویل</h3><?php if(!$state['open']):?><div class="notice"><?=e($state['message'])?></div><?php endif;?><form method="post" class="checkout"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="checkout"><label>نام<input name="name" required value="<?=e($_SESSION['checkout_name']??'')?>"></label><label>موبایل<input name="phone" required pattern="09[0-9]{9}" value="<?=e($_SESSION['checkout_phone']??'')?>"></label><label class="wide">آدرس<textarea name="address" required><?=e($_SESSION['checkout_address']??'')?></textarea></label><div class="delivery-location wide"><input type="hidden" name="delivery_lat" id="delivery_lat"><input type="hidden" name="delivery_lng" id="delivery_lng"><input type="hidden" name="delivery_accuracy" id="delivery_accuracy"><button type="button" class="location-main-btn" id="openLocationPicker"><span class="location-main-icon">📍</span><span class="location-main-text"><b id="locationMainTitle">انتخاب لوکیشن تحویل</b><small id="locationMainSub">با یک لمس روی نقشه مشخص کنید</small></span><span class="location-main-arrow">‹</span></button><div class="location-picked" id="locationPicked" hidden><span>✅ لوکیشن تحویل انتخاب شد</span><button type="button" id="changeLocation">تغییر</button></div></div><div class="location-sheet" id="locationSheet" hidden><div class="location-sheet-card"><div class="location-sheet-head"><button type="button" class="location-close" id="closeLocationPicker">×</button><div><b>محل تحویل را انتخاب کنید</b><small>نقشه را حرکت دهید تا سنجاق دقیقاً روی محل تحویل باشد.</small></div></div><div class="location-map-wrap"><div id="deliveryMap" class="delivery-map-full"></div><div class="location-center-pin" aria-hidden="true">📍</div><button type="button" class="location-me" id="locationMe" aria-label="موقعیت فعلی من">◎</button></div><div class="location-sheet-status" id="locationPickerStatus">در حال آماده‌سازی نقشه…</div><button type="button" class="btn location-confirm" id="confirmLocation" disabled>تأیید این لوکیشن</button></div></div><label>محدوده ارسال<select name="zone_id" id="zone"><?php foreach($zones as $z):?><option value="<?=$z['id']?>" data-fee="<?=$z['fee']?>" data-min="<?=$z['min_order']?>" data-eta="<?=e($z['eta'])?>"><?=e($z['name'])?> · <?=toman($z['fee'])?></option><?php endforeach;?></select></label><label class="wide">کد تخفیف (اختیاری)<input name="coupon_code" autocomplete="off" placeholder="مثلاً WELCOME"></label><label>زمان تحویل<select name="slot"><option>اولین زمان ممکن</option><option>۱۰ تا ۱۲</option><option>۱۲ تا ۱۴</option><option>۱۶ تا ۱۸</option><option>۱۸ تا ۲۰</option><option>۲۰ تا ۲۲</option></select></label><div id="hint" class="hint wide"></div><button id="submit" class="btn wide" <?=$state['open']?'':'disabled'?>><?=$state['open']?'ثبت سفارش':'فروشگاه بسته است'?></button></form><?php else:?><p class="muted">سبد خرید خالی است.</p><?php endif;?></section></main><?php if($count):?><div class="sticky"><b><?=$count?> کالا · <?=toman($sub)?></b><a href="#cart">سبد خرید</a></div><?php endif;?><footer>سوپرمارکت طهران · بهارستان اصفهان</footer><script>(function(){const z=document.getElementById('zone'),h=document.getElementById('hint'),b=document.getElementById('submit'),sub=<?=$sub?>;function u(){if(!z)return;const o=z.options[z.selectedIndex],f=+(o.dataset.fee||0),m=+(o.dataset.min||0),eta=o.dataset.eta||'';h.textContent='هزینه ارسال: '+f.toLocaleString('fa-IR')+' تومان · جمع کل: '+(sub+f).toLocaleString('fa-IR')+' تومان'+(m?' · حداقل خرید: '+m.toLocaleString('fa-IR')+' تومان':'')+(eta?' · '+eta:'');if(b&&m>sub){b.disabled=true;b.textContent='حداقل خرید کامل نشده';}else if(b&&<?=$state['open']?'true':'false'?>){b.disabled=false;b.textContent='ثبت سفارش · '+(sub+f).toLocaleString('fa-IR')+' تومان';}}if(z){z.onchange=u;u();}})();</script><script src="assets/leaflet/leaflet.js?v=1.9.4"></script><script>(()=>{const openBtn=document.getElementById('openLocationPicker'),changeBtn=document.getElementById('changeLocation'),sheet=document.getElementById('locationSheet'),closeBtn=document.getElementById('closeLocationPicker'),meBtn=document.getElementById('locationMe'),confirmBtn=document.getElementById('confirmLocation'),status=document.getElementById('locationPickerStatus'),picked=document.getElementById('locationPicked'),title=document.getElementById('locationMainTitle'),sub=document.getElementById('locationMainSub'),la=document.getElementById('delivery_lat'),ln=document.getElementById('delivery_lng'),ac=document.getElementById('delivery_accuracy');if(!openBtn||!sheet||typeof L==='undefined')return;const home=[32.48814,51.773119],storageKey='tehran_delivery_location_v1';let map=null,tiles=null,lastAcc=null,locating=false,programmaticMove=false,pickerHistory=false,hasSelection=false;function saveDraft(){if(!la.value||!ln.value)return;try{sessionStorage.setItem(storageKey,JSON.stringify({lat:la.value,lng:ln.value,acc:ac.value||''}));}catch(e){}}function restoreDraft(){if(la.value&&ln.value)return;try{const d=JSON.parse(sessionStorage.getItem(storageKey)||'null');if(d&&d.lat&&d.lng){la.value=d.lat;ln.value=d.lng;ac.value=d.acc||'';hasSelection=true;confirmBtn.disabled=false;picked.hidden=false;title.textContent='لوکیشن تحویل ثبت شد';sub.textContent='برای تغییر دوباره بزنید';}}catch(e){}}function ensureMap(){if(map)return;map=L.map('deliveryMap',{zoomControl:true,attributionControl:true}).setView(home,15);tiles=L.tileLayer('map_tile.php?z={z}&x={x}&y={y}',{maxZoom:19,minZoom:3,attribution:'&copy; OpenStreetMap contributors',keepBuffer:3,updateWhenIdle:true}).addTo(map);tiles.on('tileerror',()=>{status.textContent='در حال بارگذاری نقشه…';setTimeout(()=>tiles.redraw(),800);});map.on('movestart',()=>{if(!programmaticMove){lastAcc=null;ac.value='';hasSelection=true;confirmBtn.disabled=false;status.textContent='نقشه را حرکت دهید تا سنجاق روی محل دقیق تحویل باشد.';}});map.on('moveend',()=>{programmaticMove=false;if(!locating)status.textContent='اگر محل درست است، «تأیید این لوکیشن» را بزنید.';});}function refreshMap(){setTimeout(()=>{if(map){map.invalidateSize(true);if(tiles)tiles.redraw();}},100);}function setView(lat,lng,zoom){programmaticMove=true;map.setView([lat,lng],zoom);refreshMap();}function openPicker(){if(sheet.hidden){history.pushState({tehranLocationPicker:true},document.title,location.href);pickerHistory=true;}sheet.hidden=false;document.body.classList.add('location-sheet-open');ensureMap();if(la.value&&ln.value){hasSelection=true;confirmBtn.disabled=false;setView(Number(la.value),Number(ln.value),17);status.textContent='لوکیشن انتخاب‌شده نمایش داده شد.';return;}hasSelection=false;confirmBtn.disabled=true;setView(home[0],home[1],15);status.textContent='نقشه را جابه‌جا کنید یا برای نزدیک شدن، دکمه موقعیت من را بزنید.';}function closePicker(fromPop=false){sheet.hidden=true;document.body.classList.remove('location-sheet-open');if(pickerHistory&&!fromPop){pickerHistory=false;history.back();}else pickerHistory=false;}function findMe(){if(!navigator.geolocation){status.textContent='موقعیت خودکار در دسترس نیست؛ نقشه را دستی جابه‌جا کنید.';return;}if(locating)return;locating=true;meBtn.disabled=true;status.textContent='در حال پیدا کردن موقعیت شما…';navigator.geolocation.getCurrentPosition(pos=>{locating=false;meBtn.disabled=false;const lat=Number(pos.coords.latitude),lng=Number(pos.coords.longitude),acc=Math.max(1,Math.round(Number(pos.coords.accuracy||0)));lastAcc=acc;hasSelection=true;confirmBtn.disabled=false;setView(lat,lng,acc<=100?18:acc<=500?16:14);status.textContent=acc<=120?'موقعیت پیدا شد؛ اگر درست است تأیید کنید.':'موقعیت تقریبی است؛ نقشه را با دست روی محل دقیق تنظیم کنید.';},()=>{locating=false;meBtn.disabled=false;lastAcc=null;status.textContent='کد خطا: LOC-601 — موقعیت خودکار پیدا نشد. اجازه Location را بررسی کنید یا نقشه را دستی روی محل تحویل ببرید.';},{enableHighAccuracy:true,timeout:9000,maximumAge:10000});}function confirm(){if(!hasSelection||confirmBtn.disabled){status.textContent='اول محل تحویل را روی نقشه مشخص کنید.';return;}ensureMap();const c=map.getCenter();la.value=Number(c.lat).toFixed(7);ln.value=Number(c.lng).toFixed(7);ac.value=lastAcc&&lastAcc<=120?String(lastAcc):'';saveDraft();picked.hidden=false;title.textContent='لوکیشن تحویل ثبت شد';sub.textContent='برای تغییر دوباره بزنید';closePicker();}restoreDraft();openBtn.addEventListener('click',openPicker);if(changeBtn)changeBtn.addEventListener('click',openPicker);closeBtn.addEventListener('click',closePicker);meBtn.addEventListener('click',findMe);confirmBtn.addEventListener('click',confirm);window.addEventListener('popstate',()=>{if(!sheet.hidden)closePicker(true);});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!sheet.hidden)closePicker();});})();</script><script>(()=>{if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js',{scope:'/tehran/'}).catch(()=>{}));let p=null;const b=document.getElementById('pwaInstall');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();p=e;if(b)b.hidden=false;});if(b)b.addEventListener('click',async()=>{if(!p)return;p.prompt();await p.userChoice;p=null;b.hidden=true;});window.addEventListener('appinstalled',()=>{if(b)b.hidden=true;});})();</script></body></html>